the latest range is kept as a holdout (the angle''s requests then need at least two ranges).","type":"boolean"},"method_id":{"description":"A method of the research library (get_research_library).","enum":["conditional_distribution","threshold_sensitivity","streak_persistence","regime_comparison","cohort_comparison","quantile_ranking","lead_lag","correlation_dependency"],"type":"string"},"multiple_testing_policy":{"description":"NONE only for a single comparison.","enum":["NONE","BONFERRONI","HOLM","BENJAMINI_HOCHBERG"],"type":"string"},"outcome_horizon_periods":{"description":"Analysis periods one outcome spans. Limits: from 1 to 260.","type":"integer"},"outcome_price":{"anyOf":[{"additionalProperties":false,"properties":{"column":{"description":"The numeric price-level column (for example close) the backend computes the forward return from; never a return column.","type":"string"},"data_request_id":{"description":"The angle''s own request id (one of its data_requests) that holds the price column.","type":"string"}},"required":["data_request_id","column"],"type":"object"},{"type":"null"}],"description":"For a forward-return outcome (PERCENT or DECIMAL): the request and price column it is computed from; else null."},"outcome_unit":{"enum":["PERCENT","DECIMAL","OTHER"],"type":"string"},"pairwise_comparisons":{"description":"Limits: from 0 to 20000.","type":"integer"},"parameters":{"additionalProperties":false,"description":"Every field is present; null when the angle''s method does not use it.","properties":{"baseline_mode":{"anyOf":[{"enum":["COMPLEMENT","ALL"],"type":"string"},{"type":"null"}],"description":"conditional_distribution / threshold_sensitivity: compare with the rows without the condition (COMPLEMENT) or with every row (ALL)."},"buckets":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"quantile_ranking: the number of equal-count buckets."},"comparison":{"anyOf":[{"enum":["PAIRWISE","VS_REST","FIRST_VS_OTHERS"],"type":"string"},{"type":"null"}],"description":"regime_comparison / cohort_comparison: which differences are tested."},"correlation_method":{"anyOf":[{"enum":["PEARSON","SPEARMAN"],"type":"string"},{"type":"null"}],"description":"lead_lag / correlation_dependency: the correlation."},"groups":{"anyOf":[{"items":{"type":"string"},"type":"array"},{"type":"null"}],"description":"regime_comparison / cohort_comparison: the group labels, in the order the hypothesis reads (differences are earlier minus later)."},"lags":{"anyOf":[{"items":{"type":"integer"},"type":"array"},{"type":"null"}],"description":"lead_lag: the lags tested, in analysis periods."},"primary_lag":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"lead_lag: the predeclared lag (one of lags); correlation_dependency: the lag of the main correlation (null for none)."},"rolling_window":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"correlation_dependency: the rolling window in periods, or null."},"streak_lengths":{"anyOf":[{"items":{"type":"integer"},"type":"array"},{"type":"null"}],"description":"streak_persistence: the streak lengths tested."},"threshold_operator":{"anyOf":[{"enum":[">=","<="],"type":"string"},{"type":"null"}],"description":"threshold_sensitivity: signal >= or <= each threshold."},"thresholds":{"anyOf":[{"items":{"type":"number"},"type":"array"},{"type":"null"}],"description":"threshold_sensitivity: the signal thresholds tested."}},"required":["thresholds","threshold_operator","lags","primary_lag","buckets","groups","comparison","streak_lengths","rolling_window","baseline_mode","correlation_method"],"type":"object"}},"required":["method_id","parameters","outcome_horizon_periods","outcome_unit","candidate_count","pairwise_comparisons","multiple_testing_policy","holdout_required","outcome_price"],"type":"object"},"relationships":{"description":"Catalog relationships between this angle''s requests ([] for none).","items":{"additionalProperties":false,"description":"data_need_spec/v2 (AI_ENABLE_COMPOSITE_KEYS, IP1 Stage B): a relationship names every entity key pair.","properties":{"as_of_direction":{"anyOf":[{"enum":["BACKWARD"],"type":"string"},{"type":"null"}],"description":"AS_OF only; else null."},"effective_from_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EFFECTIVE_DATED only: catalog column; else null."},"effective_to_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EFFECTIVE_DATED only: catalog column; else null."},"join_semantics":{"description":"One of the relationship''s supported_join_semantics in the catalog.","enum":["CURRENT_STATE","EXACT_DATE","AS_OF","EFFECTIVE_DATED"],"type":"string"},"join_type":{"description":"INNER restricts the left request to rows with a match in the right request''s scope; LEFT leaves it unrestricted. Each request is delivered as its own dataset; the analysis joins them.","enum":["INNER","LEFT"],"type":"string"},"left_columns":{"description":"Every entity key column of the catalog relationship on this side (the catalog''s request_key_columns), in the order of its left_columns / right_columns without the time column (a composite key such as ticker, broker, investor_type and market_board names all of them).","items":{"type":"string"},"type":"array"},"left_request_id":{"type":"string"},"left_time_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EXACT_DATE / AS_OF: the catalog left time column; else null."},"relationship_id":{"description":"Catalog relationship_id between the two requests'' tables.","type":"integer"},"right_columns":{"description":"The matching right-side key columns, pair by pair with left_columns.","items":{"type":"string"},"type":"array"},"right_request_id":{"type":"string"},"right_time_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EXACT_DATE / AS_OF: the catalog right time column; else null."}},"required":["relationship_id","left_request_id","left_columns","right_request_id","right_columns","join_type","join_semantics","left_time_column","right_time_column","as_of_direction","effective_from_column","effective_to_column"],"type":"object"},"type":"array"}},"required":["angle_id","design","data_requests","relationships","broad_scope"],"type":"object"},"type":"array"},"data_as_of_policy":{"anyOf":[{"enum":["CONVERSATION","NEWEST"],"type":"string"},{"type":"null"}],"description":"Null or CONVERSATION: a range ending LATEST ends at the conversation''s data date. NEWEST only when the user asks for newer data; the answer then states both dates."},"question":{"description":"The user''s question, restated.","type":"string"},"spec_version":{"enum":["data_need_spec/v2"],"type":"string"},"subject":{"additionalProperties":false,"properties":{"asset_type":{"anyOf":[{"type":"string"},{"type":"null"}]},"data_domain":{"type":"string"},"entity_type":{"type":"string"}},"required":["data_domain","entity_type","asset_type"],"type":"object"},"time_basis":{"description":"HISTORICAL_DESCRIPTIVE (normal) or POINT_IN_TIME (as known then).","enum":["HISTORICAL_DESCRIPTIVE","POINT_IN_TIME"],"type":"string"}},"required":["spec_version","question","subject","angles","data_as_of_policy","time_basis"],"type":"object"}',
     'Before presenting a multi-angle Research Plan, check every angle''s design and data. Send one entry per planned angle: angle_id, its design (method from get_research_library, parameters, horizon, unit, comparisons, multiple-testing policy, holdout, and for a forward-return outcome the request and price column) and its DataNeedSpec v2 data_requests and relationships in the angle''s own ids. The backend checks each design against the method''s rules and data requirements, merges equal requests of different angles into one bundle when they fit, splits the angles into a few bundle groups only when they do not, validates each group and estimates its extraction without reading data. Returns FEASIBLE with the bundle groups, each angle''s bundle request and range ids and the columns it may use (its data contract); NOT_FEASIBLE naming the angles that cannot be served; or REVISION_REQUIRED with issues by angle. When the question names specific entities (for example BBCA), each request reads only those entities (a scope predicate on its entity column); a request that must read every entity (a market benchmark, a cross-section) is declared in that angle''s broad_scope with the reason. Present the plan only after FEASIBLE, with exactly the angles and designs checked.'),
    ('run_python', 'v8', 'v9', '{"additionalProperties":false,"properties":{"code":{"description":"Python to run in the session''s namespace. Limits: at most 20000 characters.","type":"string"},"complete":{"anyOf":[{"type":"boolean"},{"type":"null"}],"description":"true on the last call: when this code runs OK the backend calls complete_analysis at once and returns its result with this one; null or false keeps the session open."},"session_id":{"description":"Limits: matching ^sess_[0-9a-f]{24}$.","type":"string"}},"required":["session_id","code","complete"],"type":"object"}',
     'Run Python in the session. pandas as pd, numpy as np and saniti with all its helpers are pre-bound; TA-Lib (import talib), scipy, statsmodels, polars, duckdb and matplotlib are available. Read data only through the helpers: load(request) returns a whole dataset (every row of every range, including warm-up history), load_range(request, range_id, include_buffers=False) one approved range (also saniti.range; plain range() is Python''s built-in), in_period(frame, request) the mask of the rows inside the approved ranges (count and summarise only those; warm-up rows feed indicators), sql(query) DuckDB over one view per logical name, join(relationship_id) the approved relationship with its point-in-time semantics, quality(request) the Data Quality Manifest, requests() and manifest() the bundle, resample(frame, request) the catalog rules. Reads outside the helpers count as not processed. Each dataset of the session shows materialize: DIRECT (load() may read it whole) or AGGREGATE_FIRST (reduce it in sql() first, e.g. GROUP BY its entity and date columns): load(), range() and sql() refuse a pandas frame larger than the session''s frame budget with MaterializationLimitExceeded, before anything is loaded; the session, its data and variables stay, so revise the code, never the data need. Write any logic you need; define functions and call them later. Emit results with emit_table(name, frame), emit_json(name, value), emit_text(name, text), emit_chart(figure, name, title), emit_file(name, data, format); emit_table and emit_json take units={column: ''FRACTION'' | ''PERCENT'' | ''P_VALUE''} for every column holding a share or a return as a decimal, a value already in percent, or a p-value, so the answer''s value references are formatted by the data''s unit, and definition={''filters'': [{''column'', ''operator'', ''value''}], ''period'': {''start'', ''end''}, ''entities'', ''thresholds'', ''notes''}: how the result was made beyond the data request (filters in the data need''s operators EQ, NEQ, GT, GTE, LT, LTE, IN, NOT_IN, BETWEEN, IS_NULL, IS_NOT_NULL; {} when the code applied none), which later turns read instead of guessing; complete_analysis does not release a table or JSON without one. A released detail table keeps the identifier columns that define its condition (for example the broker of a broker-level condition), because later turns can only recap what a released table holds (event_summary keeps per-date aggregates only). A table of an earlier result opened with load_output carries its definition in .attrs; a table this session emitted is loaded the same way, by output_id or name, from the next run_python (label NOT_RELEASED until released), and save_table(name, frame) / load_table(name) keep working tables by name within the session''s working_table_bytes (never released, never cited). Each emit returns output metadata and the tool result lists output_ids. print() is diagnostics only. Results: OK; SCRIPT_ERROR with error_type, line, field (e.g. a missing column) and traceback: fix the code and rerun (earlier variables remain); the tables that run emitted are listed as discarded_outputs and never released, so emit them again in the run that succeeds; TIMEOUT (the execution was interrupted, the session remains); INSUFFICIENT_INPUT_DATA after saniti.insufficient_data(request, range_id, value, unit, reason): revise the DataNeedSpec (for example more history). No network, database, subprocess or writes outside intermediate_path(name). Named calendar-period returns (YTD, month, quarter, year, a comparable calendar period) use period_return(request, range_id, value_column=''close''): one row per entity with base_date, base_value (the last valid value strictly before the range start), end_date, end_value (the last valid value on or before the range end), return_decimal, return_pct (full precision) and calculation_status (COMPLETE, NO_PRIOR_CLOSE, NO_END_VALUE, INVALID_BASE_VALUE, INSUFFICIENT_INPUT_DATA, DUPLICATE_BOUNDARY_OBSERVATION); it needs history_buffer 1 TRADING_OBSERVATIONS on the request. A later data need of this answer can join this session instead (attach_data_bundle; the variables stay). Event study: event_study(request, event, outcome, horizon, range_id=None, overlap_policy=''NON_OVERLAPPING'', baseline=''ALL_ELIGIBLE'', min_events=None, holdout_start=None, outcome_unit=None, name=None) measures the outcome after an event against a baseline. event is a condition expression over the request''s columns, per entity and past values only (+ - * / **, comparisons, & | ~, abs log exp sqrt sign min max where, lag(x, k), rolling_sum(x, n), rolling_mean(x, n)), e.g. ''close / lag(close, 1) - 1 <= -0.05''; outcome is {''forward_return'': ''<price column>''} (add ''request'': ''<data_request_id>'' when the price is in another request); horizon counts observations; the request needs one row per entity and date. NON_OVERLAPPING keeps an entity''s next event only a horizon after the last one; ALL_ELIGIBLE compares with every row, NON_EVENT with the rows without the event; holdout_start adds IN_SAMPLE and OUT_OF_SAMPLE rows. It emits <name> (one row per segment: event_count, event_dates, effective_event_dates, mean, median, hit_rate, baseline_count, baseline_mean, baseline_median, delta_mean, delta_ci_low, delta_ci_high, delta_p_value with dates as clusters, censored_count, overlapping_dropped, meets_min_events), <name>_events (date, entity, outcome), <name>_baseline and <name>_flow (rows_in_window, condition_unknown, condition_true = the qualifying events, censored, overlapping_dropped, used; condition_true = censored + overlapping_dropped + used): quote each count from <name>_flow, never derive it; never overwrite or re-emit them. Backtest: backtest(request, frame, signal, exit_signal=None, stop=None, target=None, max_hold=None, fee=None, unit=None, prices=None, range_id=None, name=None) simulates long trades of a stated rule on the bundle prices: signal (and exit_signal) are boolean columns of your frame, True on the bar whose close triggers the order (filled at the next open); stop and target are fractions of the entry price; only bars inside the approved ranges trade (warm-up rows feed indicators). Use only the exit rules the user or the script states. It emits <name>_trades and <name>_summary (signals, trades, win_rate, mean and median return, average win and loss, realized_reward_risk, profit_factor, cumulative_return, max_drawdown, bars_in_period, bars_buffer): quote them, never overwrite or re-emit them.'),
    ('inspect_session', 'v2', 'v3', '{"additionalProperties":false,"properties":{"dataset":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"A dataset of the session''s bundle (logical name): its full column statistics instead of variables. Limits: at most 120 characters."},"max_rows":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"Preview rows per DataFrame (default 5). Limits: from 0 to 20."},"names":{"anyOf":[{"items":{"type":"string"},"type":"array"},{"type":"null"}],"description":"Variables to describe with a preview; null lists every variable (names, types, shapes). Limits: at most 20 items."},"session_id":{"description":"Limits: matching ^sess_[0-9a-f]{24}$.","type":"string"}},"required":["session_id","names","max_rows","dataset"],"type":"object"}',
     'Describe session variables: with names null, every variable (name, type, shape); with names, up to 20 variables with dtypes and up to max_rows preview rows. Use it to check intermediate results before emitting outputs. With dataset, the profiler''s statistics of every column of that dataset (nulls, min/median/max, distinct counts, entities with gaps), no rows.'),
    ('get_session_output', 'v2', 'v3', '{"additionalProperties":false,"properties":{"execution_id":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"An execution instead of an output: its code, what it read and the outputs it released. Limits: matching ^exe_[0-9a-f]{24}$."},"include_content":{"anyOf":[{"type":"boolean"},{"type":"null"}],"description":"With execution_id: true also returns the code."},"limit":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"Rows (tables) or chunks (text) to return; default 50. Limits: from 1 to 200."},"offset":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"First row (tables) or chunk (text); default 0. Limits: at least 0."},"output_id":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Limits: matching ^out_[0-9a-f]{24}$."},"ref":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The value reference of an output (out.o3), instead of output_id. Limits: matching ^(out\\.)?o[1-9][0-9]{0,3}$."},"session_id":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The session that made the output; null for an output of an earlier answer. Limits: matching ^sess_[0-9a-f]{24}$."}},"required":["session_id","output_id","ref","execution_id","include_content","offset","limit"],"type":"object"}',
     'Read back one output: table rows page by page (offset, limit), JSON content or text chunks; charts and files return metadata only. released is false until complete_analysis passes: only released outputs may be cited in the final answer. An output of an earlier answer opens by its ref (out.o3) or output_id, also after the sandbox deleted it; execution_id opens the code an execution ran (include_content true), what it read and released.'),
    ('get_lineage', 'v1', 'v2', '{"additionalProperties":false,"properties":{"execution_id":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Limits: matching ^exe_[0-9a-f]{24}$."},"output_id":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Limits: matching ^out_[0-9a-f]{24}$."},"ref":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The output''s value reference. Limits: matching ^(out\\.)?o[1-9][0-9]{0,3}$."}},"required":["ref","output_id","execution_id"],"type":"object"}',
     'Where an output''s numbers came from: its definition and data date, the execution that made it (code hash, modules, what it read), the bundle (source tables, row filters, ranges, rows) and the Governor queries, and earlier outputs it loaded. Give ref (out.o3), output_id or execution_id. No row values.'),
    ('export_result', 'v4', 'v5', '{"additionalProperties":false,"properties":{"column_labels":{"anyOf":[{"items":{"additionalProperties":false,"properties":{"column":{"description":"The column''s name in the output.","type":"string"},"label":{"description":"Its title in the user''s language.","type":"string"}},"required":["column","label"],"type":"object"},"type":"array"},{"type":"null"}],"description":"XLSX: the title the reader sees for each column, in the user''s language; a column not named keeps its name made readable."},"evidence_id":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"A checked claim''s evidence rows. Limits: matching ^evd_[0-9a-f]{24}$."},"format":{"enum":["CSV","XLSX","PARQUET"],"type":"string"},"include_definition":{"anyOf":[{"type":"boolean"},{"type":"null"}],"description":"XLSX: a sheet with the output''s definition (default true)."},"include_lineage":{"anyOf":[{"type":"boolean"},{"type":"null"}],"description":"XLSX: a sheet with where the data came from (default true)."},"output_id":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Limits: matching ^out_[0-9a-f]{24}$."},"ref":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The output''s value reference. Limits: matching ^(out\\.)?o[1-9][0-9]{0,3}$."},"source_columns":{"anyOf":[{"items":{"additionalProperties":false,"properties":{"column":{"description":"The column''s name in the output.","type":"string"},"source_column":{"description":"The source table''s column it was copied from, exactly as the catalog names it (for example Date for trading_date).","type":"string"}},"required":["column","source_column"],"type":"object"},"type":"array"},{"type":"null"}],"description":"XLSX: the source table''s column of each column copied from it (renamed or not); a computed column is not listed."}},"required":["ref","output_id","evidence_id","format","include_definition","include_lineage","column_labels","source_columns"],"type":"object"}',
     'Write an output as a file the user downloads (CSV, XLSX with definition and lineage sheets, or PARQUET), at most 20 MB. Give ref (out.o3), output_id, or evidence_id (a checked claim''s evidence rows). Returns export_id, file name, size and format only; the answer names the file, the user downloads it. For XLSX give column_labels: the title of each column in the user''s language, as the reader should see it, and source_columns: for each column copied from a source table (renamed or not), that table''s column name; never for a computed column. The backend adds to the XLSX definition sheet what one row is and how complete each group is against the source table.'),
    ('query_metric', 'v2', 'v3', '{"additionalProperties":false,"properties":{"as_of":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Last date of trading-day periods; null: the conversation''s data date, else today. Limits: matching ^\\d{4}-\\d{2}-\\d{2}$."},"dimensions":{"anyOf":[{"items":{"type":"string"},"type":"array"},{"type":"null"}],"description":"Split by these dimensions; null: the default. Limits: at most 4 items."},"entities":{"anyOf":[{"items":{"type":"string"},"type":"array"},{"type":"null"}],"description":"Entity values (e.g. tickers). Limits: at most 100 items."},"filters":{"anyOf":[{"items":{"additionalProperties":false,"properties":{"column":{"description":"Limits: at most 63 characters.","type":"string"},"values":{"description":"Limits: 1 to 20 items.","items":{"type":"string"},"type":"array"}},"required":["column","values"],"type":"object"},"type":"array"},{"type":"null"}],"description":"Equality filters on dimensions of the metric. Limits: at most 5 items."},"metric":{"description":"A metric id from the METRICS note. Limits: matching ^[a-z][a-z0-9_]{0,63}$.","type":"string"},"periods":{"description":"Limits: 1 to 4 items.","items":{"additionalProperties":false,"properties":{"end_date":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"A date range end; null: up to as_of (the latest data). Limits: matching ^\\d{4}-\\d{2}-\\d{2}$."},"start_date":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"A date range start. Limits: matching ^\\d{4}-\\d{2}-\\d{2}$."},"trading_days":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"The last N trading days up to as_of. Limits: from 1 to 260."}},"required":["trading_days","start_date","end_date"],"type":"object"},"type":"array"}},"required":["metric","entities","filters","dimensions","periods","as_of"],"type":"object"}',
     'An official metric (listed in the METRICS note) for entities over periods, computed by the database in one summary per period: periods are trading days of the table''s own calendar up to as_of (the conversation''s data date by default) or a date range. Returns rows per dimension with days_present, first_date and last_date, and a metric ref to cite. Not for statistics, rankings across many entities or formulas: use submit_data_need_spec.'),
    ('find_web_fact', 'v2', 'v3', '{"additionalProperties":false,"properties":{"attribute":{"description":"What to find about it, e.g. ''state-owned (BUMN) or private''. Limits: at most 200 characters; at least 2 characters.","type":"string"},"subject":{"description":"The company, ticker or entity, e.g. ''BBCA''. Limits: at most 200 characters; at least 2 characters.","type":"string"}},"required":["subject","attribute"],"type":"object"}',
     'One fact that is not in the market data, from the web in about 30 seconds: for example whether a company is state-owned, its controlling shareholder, its listing status or index membership. The backend searches, keeps only values quoted verbatim from their sources and returns CONFIRMED (two independent sites or one official), CONFLICTING (every version), PARTIAL (one site) or NOT_FOUND. Ask one subject and one attribute per call; never use it for prices, volumes or any figure the database holds. A web fact describes: state it in the answer as a web fact; a calculation''s inputs come from the database. An attribute the database''s reference tables hold (sector, industry, company profile) is read with lookup_reference; this tool is refused for it until those tables have been read.'),
    ('prepare_data_bundle', 'v3', 'v4', '{"additionalProperties":false,"properties":{"need_id":{"description":"need_id of an APPROVED DataNeedSpec. Limits: matching ^need_[0-9a-f]{24}$.","type":"string"}},"required":["need_id"],"type":"object"}',
     'Extract and deliver the data of an APPROVED DataNeedSpec as one governed data bundle. The backend plans the physical extractions (column pruning, scope and join pushdown, merged or separate range windows, date or entity partitions) and the SQL Governor checks and extracts each part; nothing is sampled, truncated or re-scoped. The sandbox verifies every part, profiles the data and checks coverage. Returns READY with input_bundle_id and, per data request, rows_extracted (warm-up and forward buffer rows included), rows_in_ranges, entities, first/last date, each requested range with its actual bounds, its rows, the buffer rows before and after it and its status (OK, PARTIAL, EMPTY), quality_flags (e.g. NULL_VALUES, FREQUENCY_GAPS, HISTORY_BUFFER_SHORTFALL, EMPTY_ENTITY, DUPLICATE_KEYS) and relationship warnings; or REJECTED naming the data_request_id, the reason code and the next action. Quality flags are facts about the data to investigate and disclose, not failures. Never change the user''s scope to pass a limit: revise the DataNeedSpec only when the rejection says so. Within a conversation, a part whose Governor SQL equals one an earlier answer extracted and whose date range ends before today is reused, not extracted again, whatever its request labels (data_reuse lists each part as REUSED with when it was extracted, or EXTRACTED with the reason); each data need still gets its own bundle and session.'),
    ('open_analysis_session', 'v3', 'v4', '{"additionalProperties":false,"properties":{"close_session_id":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Optional: a session of this answer to close before opening, only when the open was refused with SESSION_LIMIT_PER_REQUEST; pick one that is completed or no longer needed (its released outputs stay readable, its variables are gone). Null otherwise. Limits: matching ^sess_[0-9a-f]{24}$."},"input_bundle_id":{"description":"input_bundle_id of a READY bundle. Limits: matching ^bundle_[0-9a-f]{24}$.","type":"string"}},"required":["input_bundle_id","close_session_id"],"type":"object"}',
     'Open a persistent Python analysis session on a READY governed bundle (input_bundle_id from prepare_data_bundle). Returns session_id, the datasets (data_request_id, logical name, columns, rows_extracted with the buffer rows, rows_in_ranges inside the approved ranges, ranges, quality flags), the relationships with their join semantics, the helper functions and the limits. Variables and functions persist across run_python calls until the session closes (idle timeout, limits, or a restart of the sandbox: then open a new session on the same bundle). Each READY bundle gets its own session. One answer may keep up to four sessions open at once, and opening one never closes another; activity in any of them keeps all of them open while the answer runs. An open beyond the limit is refused (SESSION_LIMIT_PER_REQUEST) with this answer''s open sessions listed: continue in one of them, or open again with close_session_id naming a completed or unneeded one of them.'),
    ('complete_analysis', 'orc-v2', 'orc-v3', '{"additionalProperties":false,"properties":{"session_id":{"description":"Limits: matching ^sess_[0-9a-f]{24}$.","type":"string"}},"required":["session_id"],"type":"object"}',
     'Finish the analysis of a session. The backend builds the ExecutionManifest and runs the Coverage Validator: every approved data request and range must have been delivered as approved and read in full through the saniti helpers in a successful execution, with at least one output. Returns final_status (data_coverage PASS/FAIL, sandbox_execution, calculation_validation NOT_PERFORMED, evidence_label, warnings, claims_allowed, claims_forbidden) and, on PASS, the released outputs with their content (JSON outputs and the first table rows). Only released outputs may be cited in the answer; disclose the warnings. On FAIL follow next_action: RUN_PYTHON (read what was not processed, then complete again), REVISE_DATA_NEED_SPEC, or REPORT_LIMITATION. The backend does not recalculate your formulas: never say a calculation was independently verified. Exception: the tables of saniti.event_study are recomputed by the backend from their declaration. final_status.event_studies lists each study (PASS, FAIL with CALCULATION_MISMATCH, INVALID) and verified_output_ids the matched tables; calculation_validation is then PARTIAL (other outputs exist) or FORMULA_AND_STATISTICS_VERIFIED. Only those tables may be called independently recalculated; a FAIL makes the completion INCOMPLETE: run the event study again and complete again. The tables of saniti.backtest are re-run by the backend on the bundle prices from their signal dates: final_status.backtests lists each (PASS, FAIL with CALCULATION_MISMATCH, INVALID); the signals themselves are the code''s and are not recomputed.'),
    ('lookup_reference', 'v2', 'v3', '{"additionalProperties":false,"properties":{"columns":{"description":"Columns to return (the entity column is always added); empty when listing. Limits: at most 8 items.","items":{"type":"string"},"type":"array"},"match":{"anyOf":[{"additionalProperties":false,"properties":{"column":{"description":"The text column to search. Limits: matching ^[A-Za-z_][A-Za-z0-9_ ]{0,62}$.","type":"string"},"text":{"description":"A case-insensitive part of its text. Limits: at most 60 characters; at least 2 characters.","type":"string"}},"required":["column","text"],"type":"object"},{"type":"null"}],"description":"A text search on one column, or null."},"table":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"A reference table, or null to list them. Limits: matching ^[A-Za-z_][A-Za-z0-9_ ]{0,62}$."},"where":{"description":"Exact-value conditions, all of them must hold. Limits: at most 4 items.","items":{"additionalProperties":false,"properties":{"column":{"description":"A column of the table, exactly as listed. Limits: matching ^[A-Za-z_][A-Za-z0-9_ ]{0,62}$.","type":"string"},"values":{"description":"Exact stored values; one value, or several for any of them. Limits: 1 to 50 items.","items":{"type":"string"},"type":"array"}},"required":["column","values"],"type":"object"},"type":"array"}},"required":["table","columns","where","match"],"type":"object"}',
     'Read the database''s reference tables (static classifications and profiles: a stock''s sector, industry, board, company name or description; a broker''s name or type). Without table: the tables and their columns with descriptions. With table: up to 100 rows, filtered by where (exact stored values; one value or several) and optionally by match (a case-insensitive part of one column''s text, e.g. a group or company name). Use it before a web lookup for any attribute these tables hold; the web is only for what they do not hold. Rows are current values, not as of past dates; dated data (prices, volumes, flows) needs a data need.'),
    ('check_references', 'v3', 'v4', '{"additionalProperties":false,"properties":{"draft":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The whole answer text you are about to send, references unchanged, or null. Limits: at most 30000 characters."},"methodology":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The methodology text you are about to send, or null. Limits: at most 30000 characters."},"references":{"description":"Value references, for example ''finding.a.estimates.primary.estimate|pp:2''. Limits: at most 40 items.","items":{"type":"string"},"type":"array"}},"required":["references","draft","methodology"],"type":"object"}',
     'Shows what value references render to before you write the answer: give the addresses (with or without {{ }} and a format) and get each one''s displayed value, or why it does not resolve and the addresses that exist. Reads only this run''s results; no data is fetched or computed. With draft (the whole answer text you are about to send, every sentence, its references unchanged, never shortened with ...) and methodology (the methodology text you are about to send) it also lists what the answer checks would refuse: figures typed without a reference, with the addresses that equal them, and numbers without a source. Pass them in the check you already make before answering; it does not count as a refusal.'),
    ('research_web', 'v2', 'v3', '{"additionalProperties":false,"properties":{"expected_shape":{"anyOf":[{"enum":["FACT","NUMBER","EVENT","SERIES","LIST"],"type":"string"},{"type":"null"}],"description":"The shape the answer should have, or null when not known."},"need":{"description":"What to find, in words, e.g. ''nilai ekspor Indonesia per tahun sejak 2018''. Limits: at most 500 characters; at least 3 characters.","type":"string"},"purpose":{"description":"CITE: values to state in the answer; CONTEXT: background for an analysis of the data.","enum":["CITE","CONTEXT"],"type":"string"},"subjects":{"description":"Companies or entities the same need is asked about, one lookup each; empty for one need. Limits: at most 30 items.","items":{"type":"string"},"type":"array"}},"required":["need","purpose","expected_shape","subjects"],"type":"object"}',
     'Information that is not in the market database, from the web, for context or when the database lacks it: a fact, a figure, an event with its dates, a series over periods (for example yearly exports) or a list (for example the banks a group controls). Give one need in words, its purpose (CITE a value in the answer, CONTEXT for an analysis) and the expected shape when you know it; the same need about several companies is one call with them as subjects. The web governor searches, keeps only items quoted verbatim from their sources, labels false conflicts (different periods, definitions, units or releases) and, for a real conflict, the version it prefers (chosen_by_ai) with every version kept. Never use it for prices, volumes, flows or any figure the database holds; a web number describes and is never an input of a calculation, while an event date may set an analysis period. A run has a limited web budget: ask for what the answer needs. Each item has a ref: cite a number as {{<ref>.value_as_written}} (as its source writes it) or {{<ref>.value}} (the value at full scale), and a list or a short value as {{<ref>.value}}; the text shows the value without a link, and its source page is listed in the answer''s Sources panel. A fact''s statement is never inserted: say it in the reader''s language, in your own words, and put {{<ref>.value}} right after it, which shows nothing in the text and records the statement''s source; a figure the statement or its quote gives ("5,1%") may be written in those words, and it is checked against that quote. An attribute the database''s reference tables hold (sector, industry, company profile) is read with lookup_reference; this tool is refused for it until those tables have been read.'),
    ('read_conversation_memory', 'v1', 'v2', '{"additionalProperties":false,"properties":{"item":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"For code: an execution_id (exe_...); for catalog: a table name; else null."},"offset":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"Where a long text continues (next_offset of the previous page). Limits: at least 0."},"run_id":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The run as its memo names it (## <run_id>); null lists the runs, or with section catalog or data_record reads the conversation''s data record."},"section":{"anyOf":[{"enum":["memo","message","answer","note","plan","refusals","decisions","web","code","catalog","sources","reasoning","data_record"],"type":"string"},{"type":"null"}],"description":"What to read of the run; null: its memo and the sections it has."}},"required":["run_id","section","item","offset"],"type":"object"}',
     'Read what an earlier run of this conversation kept: its memo, the message, the full answer (with assumptions, limitations and methodology), the model''s note, the plan, every refusal with the draft it refused, the design values and their origin, the web facts with quotes and links, the code it ran, the catalog details it read, the values it made citable, or its reasoning. Without run_id: the list of runs. Long texts come in pages: call again with next_offset. No new data is read.'),
    ('attach_data_bundle', 'v1', 'v2', '{"additionalProperties":false,"properties":{"input_bundle_id":{"description":"input_bundle_id of the READY bundle to attach. Limits: matching ^bundle_[0-9a-f]{24}$.","type":"string"},"session_id":{"description":"The open analysis session of this answer. Limits: matching ^sess_[0-9a-f]{24}$.","type":"string"}},"required":["session_id","input_bundle_id"],"type":"object"}',
     'Attach a READY bundle (input_bundle_id from prepare_data_bundle) to an open analysis session of this answer instead of opening a new session: every variable, working table and output of the session stays, and the new data requests load by their names at once. Use it when the analysis finds, midway, that it needs more data (another table, a missed column, a comparison set): submit a data need with only the extra requests and attach_to_session_id, and the backend attaches its bundle for you. The bundle must have the session''s reference date and new request names; a session takes at most two attached bundles, and its bundles together stay within one bundle''s size limit. Data of an attached bundle the analysis never reads is reported as unused, not as a failure; data it reads is checked in full at complete_analysis like any other. A refusal names the reason and the capacity left: then open a new session on the bundle (open_analysis_session). Never for a research session.'),
    ('get_dimension_values', 'v3', 'v4', '{"additionalProperties":false,"properties":{"column":{"description":"A groupable text column of that table (not its entity column). Limits: matching ^[A-Za-z_][A-Za-z0-9_ ]{0,62}$.","type":"string"},"match":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Case-insensitive part of the value you look for (e.g. a word from the request), or null for every value. Limits: at most 60 characters."},"table":{"description":"A static catalog table (no time column), e.g. a reference table of classifications. Limits: matching ^[A-Za-z][A-Za-z0-9_]{0,62}$.","type":"string"}},"required":["table","column","match"],"type":"object"}',
     'List the exact stored values of one category column (a groupable text column of a static catalog table), optionally only those containing match. An entity column (tickers, broker codes) or a dated table is refused: find an entity''s code with search_values. Use it to write a scope predicate or a grouping key with the exact data value (for example the stored spelling of a classification the user named). Returns values only, at most 200, never counts or measures: it is not a data answer.'),
    ('search_values', 'v1', 'v2', '{"additionalProperties":false,"properties":{"column":{"description":"The text column of the scope predicate: an entity column (ticker, Symbol, broker) or a category column. Limits: matching ^[A-Za-z_][A-Za-z0-9_ ]{0,62}$.","type":"string"},"table":{"description":"The catalog table the scope will read (dated or static). Limits: matching ^[A-Za-z][A-Za-z0-9_]{0,62}$.","type":"string"},"terms":{"description":"The user''s words, one per entity or value, as written (a code, a name, initials such as BRI, part of a name). Limits: 1 to 10 items; each item at most 60 characters, matching \\S.","items":{"type":"string"},"type":"array"}},"required":["table","column","terms"],"type":"object"}',
     'Match the user''s words to the stored values of one text column before writing them into a scope: an exact code in any letter case, a company or broker name, its short name or initials ("BRI" -> BBRI), or part of a name. Each term returns found and value (the stored value to type), or candidates with their names when it is not found or ambiguous: take the candidate the user means, or ask the user when several fit. Use it for every name that is not a stored code; a value that is not stored is refused at approval. Values and names only, never counts or measures: it is not a data answer.'),
    ('get_method_guide', 'v1', 'v2', '{"additionalProperties":false,"properties":{"name":{"description":"A name from analysis_methods (for example event_study), or a research library method_id while multi-angle research is offered. Limits: at most 64 characters.","type":"string"}},"required":["name"],"type":"object"}',
     'Open the manual of one analysis method or helper listed in analysis_methods (the menu at the start of the run and in get_system_capabilities): what it is for and when not to use it, its inputs with their defaults, its limits, what the backend checks and what it does not, its results and how to cite them, common errors from earlier runs and tested examples. Open it before using a method the first time in a conversation; a manual opened earlier in the conversation is already in the context and need not be opened again.'),
    ('run_research_code', 'v2', 'v3', '{"additionalProperties":false,"properties":{"bundle_group_id":{"description":"The bundle group whose session runs the code, e.g. g1. Limits: matching ^g[1-9][0-9]?$.","type":"string"},"code":{"description":"Python for that group''s session. Limits: at most 20000 characters.","type":"string"}},"required":["bundle_group_id","code"],"type":"object"}',
     'Run Python in one bundle group''s session (the helpers of run_python plus saniti.research_conditional, research_persistence, research_group_comparison, research_quantiles, research_temporal_dependency and research_custom). Record every angle of the group exactly once with its helper, starting from the angle''s example call in the session''s research view: request is the data request id string, each role an expression over that request''s columns, and the outcome {''forward_return'': ''<price column>''}, with ''request'': ''<request id>'' added when the price column is in another request of the angle''s contract (the backend computes it over the approved horizon; never a price level or a trailing return column). The thresholds, lags, buckets, groups and horizon come from the approved plan. Moving to another group completes the open one first. Read every dataset of the group through the saniti helpers.')
) AS next(name, from_version, version, input_schema, purpose)
  ON previous.tool_name = next.name AND previous.version = next.from_version;

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE NOT is_active AND ((tool_name = 'submit_data_need_spec' AND version = 'v15') OR (tool_name = 'check_research_feasibility' AND version = 'v7') OR (tool_name = 'run_python' AND version = 'v9') OR (tool_name = 'inspect_session' AND version = 'v3') OR (tool_name = 'get_session_output' AND version = 'v3') OR (tool_name = 'get_lineage' AND version = 'v2') OR (tool_name = 'export_result' AND version = 'v5') OR (tool_name = 'query_metric' AND version = 'v3') OR (tool_name = 'find_web_fact' AND version = 'v3') OR (tool_name = 'prepare_data_bundle' AND version = 'v4') OR (tool_name = 'open_analysis_session' AND version = 'v4') OR (tool_name = 'complete_analysis' AND version = 'orc-v3') OR (tool_name = 'lookup_reference' AND version = 'v3') OR (tool_name = 'check_references' AND version = 'v4') OR (tool_name = 'research_web' AND version = 'v3') OR (tool_name = 'read_conversation_memory' AND version = 'v2') OR (tool_name = 'attach_data_bundle' AND version = 'v2') OR (tool_name = 'get_dimension_values' AND version = 'v4') OR (tool_name = 'search_values' AND version = 'v2') OR (tool_name = 'get_method_guide' AND version = 'v2') OR (tool_name = 'run_research_code' AND version = 'v3'))) <> 21 THEN
        RAISE EXCEPTION 'The value limits in the argument descriptions tool versions were not registered';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'submit_data_need_spec' AND version = 'v15' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'check_research_feasibility' AND version = 'v7' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'run_python' AND version = 'v9' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'inspect_session' AND version = 'v3' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'get_session_output' AND version = 'v3' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'get_lineage' AND version = 'v2' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'export_result' AND version = 'v5' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'query_metric' AND version = 'v3' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'find_web_fact' AND version = 'v3' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'prepare_data_bundle' AND version = 'v4' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'open_analysis_session' AND version = 'v4' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'complete_analysis' AND version = 'orc-v3' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'lookup_reference' AND version = 'v3' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'check_references' AND version = 'v4' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'research_web' AND version = 'v3' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'read_conversation_memory' AND version = 'v2' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'attach_data_bundle' AND version = 'v2' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'get_dimension_values' AND version = 'v4' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'search_values' AND version = 'v2' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'get_method_guide' AND version = 'v2' AND input_schema::text LIKE '%Limits:%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'run_research_code' AND version = 'v3' AND input_schema::text LIKE '%Limits:%') THEN
        RAISE EXCEPTION 'The value limits in the argument descriptions contracts are not in the registered rows';
    END IF;
END
$verify$;

COMMIT;
